{"content": "#!/usr/bin/env python3
"""Probe which models a Bedrock OpenAI-compatible bearer token can use.

Token source order: $AWS_BEARER_TOKEN_BEDROCK, else COPILOT_PROVIDER_API_KEY
read from a running copilot process's environment (never printed).
"""
import json
import os
import subprocess
import sys
import urllib.request
import urllib.error

REGION = os.environ.get("BEDROCK_REGION", "us-east-2")
BASE = f"https://bedrock-runtime.{REGION}.amazonaws.com/openai/v1"
PROXY = os.environ.get("https_proxy") or os.environ.get("HTTPS_PROXY") or "http://proxy-dmz.intel.com:912"

def get_token():
    tok = os.environ.get("AWS_BEARER_TOKEN_BEDROCK", "")
    if tok:
        return tok, "env"
    try:
        out = subprocess.run(["pgrep", "-f", "copilot-linux-x64/copilot"],
                             capture_output=True, text=True).stdout.split()
        for pid in out:
            try:
                with open(f"/proc/{pid}/environ", "rb") as f:
                    for item in f.read().decode("utf-8", "replace").split("\0"):
                        if item.startswith("COPILOT_PROVIDER_API_KEY="):
                            return item.split("=", 1)[1], f"copilot pid {pid}"
            except (PermissionError, FileNotFoundError):
                continue
    except FileNotFoundError:
        pass
    return "", ""

def req(method, url, body=None, token=""):
    data = json.dumps(body).encode() if body is not None else None
    r = urllib.request.Request(url, data=data, method=method)
    r.add_header("Content-Type", "application/json")
    if token:
        r.add_header("Authorization", f"Bearer {token}")
    opener = urllib.request.build_opener(
        urllib.request.ProxyHandler({"https": PROXY, "http": PROXY}))
    try:
        with opener.open(r, timeout=30) as resp:
            return resp.status, resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode("utf-8", "replace")
    except OSError as e:
        return -1, str(e)

CANDIDATES = [
    "us.anthropic.claude-opus-4-8-v1:0",
    "anthropic.claude-opus-4-8-v1:0",
    "us.anthropic.claude-opus-4-5-20251101-v1:0",
    "us.anthropic.claude-opus-4-1-20250805-v1:0",
    "us.anthropic.claude-opus-4-20250514-v1:0",
    "us.anthropic.claude-sonnet-4-5-20250929-v1:0",
    "us.anthropic.claude-sonnet-4-20250514-v1:0",
    "us.anthropic.claude-haiku-4-5-20251001-v1:0",
    "us.openai.gpt-5.6-sol",
]

def main():
    token, src = get_token()
    if not token:
        print("找不到 token(环境变量和运行中的 copilot 进程都没有)"); sys.exit(1)
    print(f"token 来源: {src}(不显示内容); 出站代理: {PROXY}\n")

    code, text = req("GET", f"{BASE}/models", token=token)
    if code == 200:
        try:
            ids = [m.get("id") for m in json.loads(text).get("data", [])]
            print("GET /models 支持的模型:")
            for i in ids:
                print(" ", i)
            return
        except ValueError:
            pass
    print(f"GET /models 不可用(HTTP {code}),改用逐模型探测...\n")

    print(f"{'模型 ID':<48} 结果")
    print("-" * 90)
    for mid in CANDIDATES:
        body = {"model": mid, "max_tokens": 1,
                "messages": [{"role": "user", "content": "hi"}]}
        code, text = req("POST", f"{BASE}/chat/completions", body, token)
        if code == 200:
            verdict = "✓ 可用"
        else:
            tl = text.lower()
            if "model identifier is invalid" in tl or "validation" in tl and "model" in tl:
                verdict = "✗ 模型 ID 不存在"
            elif "access" in tl or "denied" in tl or "permission" in tl:
                verdict = "✗ 存在但没权限/未开通"
            elif "unsupported" in tl:
                verdict = "? 存在但请求形态不支持(可能可用)"
            else:
                verdict = f"? HTTP {code}: {text[:80]}"
        print(f"{mid:<48} {verdict}")

if __name__ == "__main__":
    main()
