def get_request_headers(
    self,
    credentials: Credentials,
    aws_region_name: str,
    extra_headers: dict | None,
    endpoint_url: str,
    data: str | bytes,
    headers: dict,
    api_key: str | None = None,
    supports_bearer_token: bool = True,
) -> AWSPreparedRequest:
    if not supports_bearer_token:
        aws_bearer_token: str | None = None
